    public Record_ testCreate() throws Throwable {
    Record_ entity = null;

    LOGGER.info( "Record_Test:testCreate()" );
    LOGGER.info( "-- Attempting to create a Record_");

    StringBuilder msg = new StringBuilder( "-- Failed to create a Record_" );

    try {
        entity = service.createRecord_( generateNewCommand() );
        assertNotNull( entity, msg.toString() );

        theId = entity.getRecord_Id();
        assertNotNull( theId, msg.toString() + " Contains a null primary key" );

        LOGGER.info( "-- Successfully created a Record_ with primary key" + theId );
    }
    catch (Exception e)  {
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() + entity );

        throw e;
    }
    return entity;
}

