    /**
     * Tests getting all Record_s.
     *
     * @return    Collection
     */
    public List<Record_> testGetAll() throws Throwable {
    LOGGER.info( "Record_Test:testGetAll() - Retrieving Collection of Record_s:" );

    StringBuilder msg = new StringBuilder( "-- Failed to get all Record_ : " );
    List<Record_> collection  = null;

    try {
        // call the static get method on the Record_Service
        collection = service.getAllRecord_();

        if ( collection == null || collection.size() == 0 ) {
            LOGGER.warning( unexpectedErrorMsg );
            LOGGER.warning( "-- " + msg.toString() + " Empty collection returned."  );
        }
        else {
            // Now print out the values
            Record_ currEntity  = null;
            Iterator<Record_> iter = collection.iterator();

            while( iter.hasNext() ) {
                // Retrieve the entity
                currEntity = iter.next();

                assertNotNull( currEntity,"-- null value object in Collection." );
                assertNotNull( currEntity.getRecord_Id(), "-- value object in Collection has a null primary key" );

                LOGGER.info( " - " + currEntity.toString() );
            }
        }
    }
    catch ( Throwable e ){
        LOGGER.warning( unexpectedErrorMsg );
        LOGGER.warning( msg.toString() );

        throw e;
    }

    return( collection );
}

